import { Album, Media, MediaType } from "@parksandresorts/webapiproxy-types";
import RideStore from "@/core/stores/ride-store";
import { TodayHelper } from "@/core/helpers/today-helper";
import DateHelper from "@/core/helpers/date-helper";

export const expirationDuration = (album: Album | undefined) => {
  if (!album?.expiryDate) {
    return undefined;
  }

  const now = TodayHelper.getNow();
  const durationUntilExpirationInDays = DateHelper.durationBetween(album.expiryDate, now, "days");
  const durationUntilExpirationInHours = DateHelper.durationBetween(album.expiryDate, now, "hours");
  const durationUntilExpirationInMinutes = DateHelper.durationBetween(album.expiryDate, now, "minutes");

  return {
    days: durationUntilExpirationInDays,
    hours: durationUntilExpirationInHours % 24,
    minutes: durationUntilExpirationInMinutes % 60,
    hasExpired: durationUntilExpirationInMinutes < 0,
  };
};

/**
 * An album is considered unlocked only when `locked` is explicitly `false`.
 * While the album is still loading (`locked` is `undefined`), it is treated as locked.
 */
export const isAlbumUnlocked = (album: Album | undefined) => album?.locked === false;

export const getTitleFromRideId = (rideId: number | null | undefined) => {
  if (!rideId) {
    return undefined;
  }
  return RideStore.getRideById(rideId)?.title ?? undefined;
};

export const getMediaFileNameAndMimeType = (media: Media) => {
  const rideTitle = getTitleFromRideId(media.attractionId);
  const fileExtension = media.mediaType === "Photo" ? "png" : "mp4";
  const mimeType = media.mediaType === "Photo" ? "image/png" : "video/mp4";
  return {
    fileName: `${rideTitle}${media.referenceNumber ? ` ${media.referenceNumber}` : ""}.${fileExtension}`,
    mimeType,
  };
};

export const createFileFromMedia = async (media: Media) => {
  if (!media.url) {
    return undefined;
  }
  const data = await fetch(media.url);
  if (!data.ok) {
    throw new Error("Failed to fetch media data");
  }
  const blob = await data.blob();
  const { fileName, mimeType } = getMediaFileNameAndMimeType(media);
  return new File([blob], fileName, {
    type: mimeType,
  });
};

export const downloadFile = (url: string, fileName: string) => {
  const a = document.createElement("a");
  a.href = url;
  a.download = fileName;
  a.click();
};

export const downloadAllMedia = async (media: Array<Media>) => {
  await Promise.all(
    media.map(async (mediaItem) => {
      const file = await createFileFromMedia(mediaItem);
      if (!file) {
        return;
      }
      const url = URL.createObjectURL(file);
      downloadFile(url, getMediaFileNameAndMimeType(mediaItem).fileName);
    }),
  );
};

export const ALBUM_ID_PART_LENGTH = 3;
export const ALBUM_ID_NUMBER_OF_PARTS = 4;

export const albumIdWithHyphens = (albumId: string): string => {
  if (!(albumId.length === ALBUM_ID_PART_LENGTH * ALBUM_ID_NUMBER_OF_PARTS)) {
    return albumId;
  }
  const parts = [];
  for (let i = 0; i < ALBUM_ID_NUMBER_OF_PARTS; i++) {
    parts.push(albumId.substring(i * ALBUM_ID_PART_LENGTH, (i + 1) * ALBUM_ID_PART_LENGTH));
  }
  return parts.join("-");
};

type AlbumId = string;
export type PurchasedState = Record<AlbumId, Array<{ cartId: string; mediaIds: Array<string>; purchasedOn: string }>>;

/**
 * Since we sometimes have hashes in the URL and we get the albumId from the URL, there seem to be cases where the hash
 * gets escaped. Perhaps this is done by the browser or some other app on the user's device? When this happens, we need
 * to ignore the escaped characters to get the correct albumId, which this function handles.
 */
export function parseAlbumId(albumId: string | undefined) {
  if (!albumId) {
    return undefined;
  }
  if (albumId.includes("%")) {
    try {
      albumId = decodeURIComponent(albumId);
    } catch {
      // ignore
    }
  }
  return albumId.split(/[?#]/)[0]; // Remove any query or hash parts
}

/**
 * Gets the medias that are
 * 1. Photos
 * 2. Have an attractionId and referenceNumber
 * 3. Are configured to have a video (according to rideMediaSearchAttractions)
 * 4. Do not already have a video uploaded for them (by checking other medias with the same referenceNumber that are videos)
 * and returns them in a map by mediaId for easy lookup.
 */
export const getMediasWithUpcomingVideoById = (
  allMedia: Media[],
  rideMediaSearchAttractions: Array<{ rideId: number; hasVideo: boolean }>,
) => {
  return allMedia
    .filter((media, _i, allMedia) => {
      const hasMediaId = !!media.mediaId;
      if (!hasMediaId) {
        return false;
      }
      const isPhotoWithAttractionCodeAndReferenceNumber =
        media.mediaType === MediaType.PHOTO && media.attractionId !== undefined && media.referenceNumber !== undefined;
      if (!isPhotoWithAttractionCodeAndReferenceNumber) {
        return false;
      }
      const shouldHaveVideoAccordingToConfig = rideMediaSearchAttractions.some(
        (ride) => ride.rideId === media.attractionId && ride.hasVideo,
      );
      if (!shouldHaveVideoAccordingToConfig) {
        return false;
      }
      const otherMediaIsVideoForThisPhoto = allMedia.some(
        (otherMedia) =>
          otherMedia.referenceNumber === media.referenceNumber && otherMedia.mediaType === MediaType.VIDEO,
      );
      return !otherMediaIsVideoForThisPhoto;
    })
    .reduce<Record<string, Media>>((acc, media) => {
      acc[media.mediaId] = media;
      return acc;
    }, {});
};
