/**
 * The modal inside stories do not get the correct size, so we mock a size here so that the media in <FocusedMediaModal> is visible.
 * Note that the size of the media and modal is not exactly the same as on the webs, where these are properly sized based on the media size.
 * We set it to 70dvh so that both images and portrait videos look okay
 *  */
export const withFocusedMediaModalMinHeight = (Story: any) => (
  <div
    style={
      {
        "--storybook-focused-media-modal-min-height": "70dvh",
      } as React.CSSProperties
    }
  >
    <Story />
  </div>
);

/** Helper to pause execution for a given ms */
export const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Waits (up to 5s) for an element to be visible, then optionally runs `assert` on it.
 * Used for checking expected content, attribute, values etc.
 *
 * `Example usage:
 *   await waitForVisibleElement({ canvasElement, testId }); // just wait for it to appear
 *   await waitForVisibleElement({ canvasElement, testId, assert: (el) => expect(el).toHaveValue("123") });
 *   await waitForVisibleElement({ canvasElement, testId, assert: (el) => expect(el).toHaveAttribute("data-has-error", "false") });
 */
export const waitForVisibleElement = async ({
  canvasElement,
  testId,
  assert,
  timeout = 5000,
}: {
  canvasElement: HTMLElement;
  testId: string;
  assert?: (element: HTMLElement) => void;
  timeout?: number;
}) => {
  const canvas = within(canvasElement);
  await waitFor(
    () => {
      const element = canvas.getByTestId(testId);
      expect(element).toBeVisible();
      assert?.(element);
    },
    { timeout },
  );
};

/**
 * Asserts that the given testIds are NOT in the document.
 *
 * Note: a negative assertion can pass too early. If an element is going to appear
 * after a short delay but isn't rendered yet, this sees "not in document" on the
 * first check and passes immediately — before the element had a chance to render.
 * So always wait for the UI to reach its final state first (e.g. assert the
 * expected content is visible via elementIsVisible), then call this.
 */
export const elementIsNotInDocument = async ({
  canvasElement,
  testIds,
}: {
  canvasElement: HTMLElement;
  testIds: Array<string | RegExp>;
}) => {
  const canvas = within(canvasElement);
  await waitFor(
    () => {
      for (const id of testIds) {
        expect(canvas.queryByTestId(id)).not.toBeInTheDocument();
      }
    },
    { timeout: 2000 },
  );
};

/**
 * Waits for an element to be visible (up to 5s), scrolls it into view, then clicks it once.
 * Returns the clicked element.
 */
export const clickOnElement = async ({ canvasElement, testId }: { canvasElement: HTMLElement; testId: string }) => {
  const canvas = within(canvasElement);
  const element = await waitFor(
    () => {
      const el = canvas.getByTestId(testId);
      expect(el).toBeVisible();
      return el;
    },
    { timeout: 5000 },
  );
  await element.scrollIntoView({ block: "center" });
  await userEvent.click(element);
  return element;
};

/**
 * Types a value into one or more elements, in order. Pass an array of [testId, value] tuples.
 *
 * For each: waits for the element to be visible (up to 5s), scrolls to it, clears any existing
 * value, then types the new value with a delay between keystrokes (to mimic real user behavior
 * and allow the UI to react to each keystroke if needed).
 */
export const typeValue = async ({
  canvasElement,
  testCases,
}: {
  canvasElement: HTMLElement;
  testCases: Array<[testId: string, value: string]>;
}) => {
  for (const [testId, value] of testCases) {
    const element = await clickOnElement({ canvasElement, testId });
    await userEvent.clear(element); // Clear existing value, if any, before typing new one
    value && (await userEvent.type(element, value, { delay: 50 }));
  }
};

export const pasteValue = async ({
  canvasElement,
  testId,
  value,
}: {
  canvasElement: HTMLElement;
  testId: string;
  value: string;
}) => {
  await clickOnElement({ canvasElement, testId });
  await userEvent.paste(value);
};

export const searchForAlbum = async ({ canvasElement, albumId }: { canvasElement: HTMLElement; albumId: string }) => {
  const albumIdParts = albumIdWithHyphens(albumId).split("-");
  await typeValue({
    canvasElement: canvasElement,
    testCases: [
      ["digital-ride-media-search-album-form-album-code-first-part", ""],
      ["digital-ride-media-search-album-form-album-code-second-part", ""],
      ["digital-ride-media-search-album-form-album-code-third-part", ""],
    ],
  });
  // Write all relevant code parts in one go, to make sure focus automatically jumps between each input after completion
  await typeValue({
    canvasElement: canvasElement,
    testCases: [["digital-ride-media-search-album-form-album-code-first-part", albumIdParts.slice(1, 4).join("")]],
  });
  await clickOnElement({
    canvasElement: canvasElement,
    testId: "digital-ride-media-search-album-form-search-button",
  });
};

export const MOCKED_DATE = "2026-06-05T12:00:00Z";

/** Uses mocked date as "today" */
export const daysFromToday = (days: number, time?: string) => {
  const date = new Date(new Date(MOCKED_DATE).getTime() + days * 24 * 60 * 60 * 1000).toISOString();
  if (time) {
    // Enforce that time always starts with 'T' (ISO 8601 format)
    if (!/^T\d{2}:\d{2}:\d{2}/.test(time)) {
      throw new Error(
        `Invalid time format: '${time}'. Time must start with 'T' and be in the format 'THH:MM:SS[.sss][Z]'.`,
      );
    }
    // Extract date part (YYYY-MM-DD) and add time
    const datePart = date.slice(0, 10);
    return datePart + time;
  }
  return date;
};

/** Uses mocked date as "today" */
const expiryDateFromToday = (createdDaysFromToday: number) => {
  const expirationPeriod = -45;
  const date = new Date(
    new Date(MOCKED_DATE).getTime() + (createdDaysFromToday - expirationPeriod) * 24 * 60 * 60 * 1000,
  );
  date.setUTCHours(0, 0, 0, 0);
  return date.toISOString();
};

