function getMediaUrl({ mediaType, locked, landscape }: { mediaType: MediaType; locked: boolean; landscape: boolean }) {
  if (mediaType === MediaType.VIDEO) return MEDIA_URL_VIDEO;
  if (!locked) return UNLOCKED_MEDIA_URL;
  return landscape ? MEDIA_URL_LANDSCAPE_PHOTO : MEDIA_URL_PORTRAIT_PHOTO;
}

function getSmallUrl({ mediaType, locked, landscape }: { mediaType: MediaType; locked: boolean; landscape: boolean }) {
  if (mediaType === MediaType.VIDEO) return SMALL_URL_VIDEO_IMAGE;
  if (!locked) return UNLOCKED_SMALL_URL;
  return landscape ? SMALL_URL_LANDSCAPE_PHOTO : SMALL_URL_PORTRAIT_PHOTO;
}

function getMediumUrl({ mediaType, locked, landscape }: { mediaType: MediaType; locked: boolean; landscape: boolean }) {
  if (mediaType === MediaType.VIDEO) return MEDIUM_URL_VIDEO_IMAGE;
  if (!locked) return UNLOCKED_MEDIUM_URL;
  return landscape ? MEDIUM_URL_LANDSCAPE_PHOTO : MEDIUM_URL_PORTRAIT_PHOTO;
}

function getThumbUrl({ mediaType, locked, landscape }: { mediaType: MediaType; locked: boolean; landscape: boolean }) {
  if (mediaType === MediaType.VIDEO) return THUMB_URL_VIDEO_IMAGE;
  if (!locked) return UNLOCKED_THUMB_URL;
  return landscape ? THUMB_URL_LANDSCAPE_PHOTO : THUMB_URL_PORTRAIT_PHOTO;
}

const createMedia = ({
  imageNumberPrefix,
  imageNumber,
  attractionId = 123,
  createdDaysFromToday = 0,
  mediaType = MediaType.PHOTO,
  locked = true,
  landscape = true,
}: {
  imageNumberPrefix: string;
  imageNumber: string;
  attractionId?: number;
  createdDaysFromToday?: number;
  mediaType?: MediaType;
  locked?: boolean;
  landscape?: boolean;
}) => {
  return {
    mediaId: `01234-${imageNumber}-${mediaType === MediaType.PHOTO ? "0000" : "1111"}`,
    attractionId: attractionId,
    referenceNumber: `${imageNumberPrefix}-${imageNumber}`,
    createTime: daysFromToday(createdDaysFromToday),
    mediaType: mediaType,
    uploadTime: daysFromToday(createdDaysFromToday),
    locked: locked,
    orientation: landscape ? MediaOrientation.LANDSCAPE : MediaOrientation.PORTRAIT,
    expiryDate: expiryDateFromToday(createdDaysFromToday),
    url: getMediaUrl({ mediaType, locked, landscape }),
    smallUrl: getSmallUrl({ mediaType, locked, landscape }),
    mediumUrl: getMediumUrl({ mediaType, locked, landscape }),
    thumbUrl: getThumbUrl({ mediaType, locked, landscape }),
  } satisfies Media;
};

const createAlbum = ({
  albumId,
  createdDaysFromToday = 0,
  albumType,
  locked = true,
  media = [],
}: {
  albumId: string;
  createdDaysFromToday?: number;
  albumType: AlbumType;
  locked?: boolean;
  media?: Media[];
}) => {
  return {
    album: {
      albumId,
      albumType,
      name: `Gröna Lund • ${DateHelper.toStringDDShortMonth(daysFromToday(createdDaysFromToday))}`,
      accountId: "6787c6e4a9b6f87f8912dd0a",
      created: daysFromToday(createdDaysFromToday),
      visitDate: DateHelper.toStringYYYYMMDD(daysFromToday(createdDaysFromToday)),
      expiryDate: expiryDateFromToday(createdDaysFromToday),
      locked,
    } satisfies Album,
    media: {
      totalCount: media.length,
      page: 1,
      pageSize: media.length,
      hasNextPage: false,
      items: media,
    },
  };
};

