export const allAppAlbums = Object.values(albumVersions).map((version) =>
  createAlbum({ ...version, albumType: AlbumType.APP }),
);
export const allQrAlbums = Object.values(albumVersions).map((version) =>
  createAlbum({ ...version, albumType: AlbumType.QR }),
);

export const allAppAlbumsById = Object.fromEntries(allAppAlbums.map((album) => [album.album.albumId, album]));
export const allQrAlbumsById = Object.fromEntries(allQrAlbums.map((album) => [album.album.albumId, album]));

export const fetchAlbumMock = async (albumId: string): Promise<{ item: Album }> => {
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const album = allAppAlbums.find((album) => album.album.albumId === albumIdWithHyphens(albumId));
  if (album) {
    return { item: { ...album.album } };
  }
  throw new Error(`Album with id ${albumId} not found`);
};

